-- Height at a world position, or Water. Nearest cell: the grid is ~200 studs across, so interpolating
-- would imply a precision the sample does not have.
function MapTerrain.At(x, z)
	local step = (MapTerrain.HalfSize * 2) / MapTerrain.Size
	local gx = math.floor((x + MapTerrain.HalfSize) / step) + 1
	local gz = math.floor((z + MapTerrain.HalfSize) / step) + 1
	local row = MapTerrain.Heights[gz]
	if not row then return MapTerrain.Water end
	return row[gx] or MapTerrain.Water
end

return MapTerrain
